WITH per_client AS ( SELECT cliente, ROUND(AVG(diff_days), 2) AS avg_dias, COUNT(*) AS intervalos FROM ( SELECT cliente, julianday(emissao) - julianday(LAG(emissao) OVER (PARTITION BY cliente ORDER BY emissao)) AS diff_days FROM pedidos_efetivos ) WHERE diff_days IS NOT NULL GROUP BY cliente ) SELECT pc.cliente, pc.avg_dias, pc.intervalos, CASE WHEN pc.avg_dias = (SELECT MIN(avg_dias) FROM per_client) THEN 'Menor' END AS menor_tempo FROM per_client pc ORDER BY pc.avg_dias;